return ['domain'=>'publishpress-hub&& n%100<=10 ? 3 : n%100>=11 ? 4 : 5);','plural-forms'=>'nplurals=6; plural=(n == 0 ? 0 : n == 1 ? 1 : n == 2 ? 2 : n % 100 >= 3 && n % 100 <= 10 ? 3 : n % 100 >= 11 ? 4 : 5);','language'=>'ar','project-id-version'=>'PublishPress Hub 1.2.0','pot-creation-date'=>'2026-11-16T12:00:34+00:00','po-revision-date'=>'2026-11-16 12:51+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['PublishPress Hub'=>'PublishPress Hub','Centralized management hub for all PublishPress plugins - install, update, and manage licenses from one dashboard.'=>'مركز إدارة مركزي لجميع إضافات PublishPress - قم بتثبيت وتحديث وإدارة التراخيص من لوحة معلومات واحدة.','PublishPress'=>'PublishPress','https://publishpress.com'=>'https://publishpress.com','Please wait while we load the components showcase...'=>'يرجى الانتظار بينما نحمل عرض المكونات...','AI Connections'=>'AI Connections','Please wait while we load AI connections...'=>'يرجى الانتظار بينما نحمل اتصالات الذكاء الاصطناعي...','Please wait while we load the plugins dashboard...'=>'يرجى الانتظار بينما نحمل لوحة معلومات الإضافات...','Settings'=>'الإعدادات','Please wait while we load the settings page...'=>'يرجى الانتظار بينما نحمل صفحة الإعدادات...','You do not have sufficient permissions to access this page.'=>'ليس لديك أذونات كافية للوصول إلى هذه الصفحة.','Welcome'=>'مرحباً','Please wait while we load the welcome page...'=>'يرجى الانتظار بينما نحمل صفحة الترحيب...','Language pack has not been checked yet.'=>'حزمة اللغة لم يتم التحقق منها بعد.','Site locale is English. No language pack is downloaded.'=>'اللغة المستخدمة في الموقع هي الإنجليزية. لم يتم تنزيل حزمة لغة.','No language packs are registered.'=>'لا توجد حزم لغات مسجلة.','Language pack directory is not available.'=>'دليل حزمة اللغة غير متوفر.','Language pack for %1$s (%2$s) matches %3$s.'=>'تطابق حزمة اللغة لـ %1$s (%2$s) %3$s.','Language pack for %1$s (%2$s) installed for %3$s.'=>'تم تثبيت حزمة اللغة لـ %1$s (%2$s) لـ %3$s.','Language pack URL was rejected.'=>'تم رفض عنوان URL لحزمة اللغة.','Language pack download failed for %1$s (%2$s). The installed pack was left in place.'=>'فشل تنزيل حزمة اللغة لـ %1$s (%2$s). تم ترك الحزمة المثبتة في مكانها.','Language pack could not be unpacked.'=>'لم يكن بالإمكان فك حزمة اللغة.','Language pack is missing a catalog file. The installed pack was left in place.'=>'تفتقر حزمة اللغة إلى ملف الفهرس. تم ترك الحزمة المثبتة في مكانها.','Language pack JSON catalog is invalid. The installed pack was left in place.'=>'فهرس JSON لحزمة اللغة غير صالح. تم ترك الحزمة المثبتة في مكانها.','Language pack could not be stored. The installed pack was left in place.'=>'لم يكن بالإمكان تخزين حزمة اللغة. تم ترك الحزمة المثبتة في مكانها.','Language pack PHP catalog could not be built. The installed pack was left in place.'=>'لم يكن بالإمكان بناء فهرس PHP لحزمة اللغة. تم ترك الحزمة المثبتة في مكانها.','Warning: The license for %1$s has expired. %2$s'=>'تحذير: انتهت صلاحية الترخيص لـ %1$s. %2$s','Manage licenses'=>'إدارة التراخيص','Warning: %1$d plugin(s) have expired licenses: %2$s. %3$s'=>'تحذير: انتهت صلاحية تراخيص %1$d من الإضافات: %2$s. %3$s','The license server accepted your key, but this site could not save its active license. Please contact support and mention this message.'=>'قبلت خادم الترخيص مفتاحك، لكن لم يتمكن هذا الموقع من حفظ ترخيصه النشط. يرجى الاتصال بالدعم وذكر هذه الرسالة.','PublishPress actions for %s. These tools apply only to this site. If several sites are connected and the requested site is unclear, ask which site to use before calling a tool. Confirm the target site before changing site data.'=>'إجراءات PublishPress لـ %s. هذه الأدوات تنطبق فقط على هذا الموقع. إذا تم ربط عدة مواقع وكان الموقع المطلوب غير واضح، اسأل أي موقع يجب استخدامه قبل استدعاء أداة. أكد الموقع المستهدف قبل تغيير بيانات الموقع.','WordPress version'=>'إصدار WordPress','MCP Adapter version'=>'إصدار MCP Adapter','Not active'=>'غير نشط','HTTPS'=>'HTTPS','Available'=>'متاح','Required'=>'مطلوب','Application passwords'=>'كلمات مرور التطبيقات','Unavailable; check WordPress or security plugin settings'=>'غير متاح؛ تحقق من إعدادات WordPress أو إضافات الأمان','Registered actions'=>'الإجراءات المسجلة','Selected actions exposed'=>'الإجراءات المحددة مكشوفة','Changes saved.'=>'تم حفظ التغييرات.','Changes saved. Restart your AI app or refresh its PublishPress connection to update the available actions.'=>'تم حفظ التغييرات. أعد تشغيل تطبيق الذكاء الاصطناعي الخاص بك أو قم بتحديث اتصال PublishPress الخاص به لتحديث الإجراءات المتاحة.','Changes saved. Connect your AI app to continue.'=>'تم حفظ التغييرات. قم بتوصيل تطبيق الذكاء الاصطناعي الخاص بك للمتابعة.','Changes saved. Select at least one available action to continue.'=>'تم حفظ التغييرات. اختر إجراءً واحدًا متاحًا على الأقل للمتابعة.','Update WordPress to continue'=>'قم بتحديث WordPress للمتابعة','WordPress 6.9 or newer is required.'=>'يتطلب WordPress 6.9 أو أحدث.','Open WordPress updates'=>'فتح تحديثات WordPress','Install the MCP Adapter plugin'=>'تثبيت إضافة MCP Adapter','Install the official WordPress MCP Adapter plugin to connect your AI service.'=>'تثبيت إضافة MCP Adapter الرسمية لـ WordPress لتوصيل خدمة الذكاء الاصطناعي الخاصة بك.','Manage plugins'=>'إدارة الإضافات','Set up MCP Adapter'=>'إعداد MCP Adapter','Use HTTPS to connect your AI'=>'استخدم HTTPS لتوصيل الذكاء الاصطناعي الخاص بك','Both WordPress and site addresses must use HTTPS.'=>'يجب أن تستخدم كل من WordPress وعناوين الموقع HTTPS.','Open site settings'=>'فتح إعدادات الموقع','Add a PublishPress plugin with AI actions'=>'إضافة إضافة PublishPress مع إجراءات الذكاء الاصطناعي','You don\'t have any PublishPress plugins installed that support AI actions yet.'=>'ليس لديك أي إضافات PublishPress مثبتة تدعم إجراءات الذكاء الاصطناعي بعد.','Open PublishPress plugins'=>'فتح إضافات PublishPress','Allow application passwords for your account'=>'السماح لكلمات مرور التطبيقات لحسابك','Create an application password in your WordPress profile for assisted or manual setup.'=>'قم بإنشاء كلمة مرور تطبيق في ملفك الشخصي على WordPress للإعداد المساعد أو اليدوي.','Application passwords are unavailable for your account. HTTPS or security plugin settings may need attention.'=>'كلمات مرور التطبيقات غير متاحة لحسابك. قد تحتاج إعدادات HTTPS أو إضافة الأمان إلى الانتباه.','Open application passwords'=>'فتح كلمات مرور التطبيقات','PASTE_YOUR_APPLICATION_PASSWORD_HERE'=>'الصق_كلمة_مرور_التطبيق_هنا','Ask my AI to help'=>'اطلب من الذكاء الاصطناعي الخاص بي المساعدة','Recommended. Ask your AI for a setup script to run on your computer.'=>'موصى به. اطلب من الذكاء الاصطناعي الخاص بك نص برمجي للإعداد للتشغيل على جهاز الكمبيوتر الخاص بك.','Connect my AI app to PublishPress. Create a setup script and give me the exact terminal command to run it.

1. Ask me to select my AI app and OS (Windows, macOS or Linux). Use interactive choices if available, otherwise numbered options.
2. Create the script using your file tools. Request the specific permission if needed. If you cannot write locally, attach a downloadable script. Only fall back to code with save instructions when neither is possible. Use PowerShell on Windows and an appropriate script on macOS or Linux. Do not stop at explaining access limitations or provide only JSON.
3. Configure this local stdio server:
Name: %3$s
Display name: %4$s
Command: npx
Arguments: -y @automattic/mcp-wordpress-remote@latest
Environment: OAUTH_ENABLED=false, WP_API_URL=%1$s, WP_API_USERNAME=%2$s
Read WP_API_PASSWORD through a hidden terminal prompt.
Hub write access: %5$s. Only individually selected actions are exposed.
4. Check Node.js and npx. If missing, link to the official installer and tell me to reopen the terminal. Back up existing settings. Use a JSON/TOML parser or supported client command to merge only this server, preserving other settings and sites. Stop on invalid configuration or a conflicting endpoint. If replacing an old PublishPress desktop extension for this site, guide me to disable only that extension to avoid duplicate connections. Quote paths and values safely.
5. Give brief run, restart and approval instructions. Verify through the connection or give me a prompt to test in the app: confirm the site URL, list actual tools and perform a read-only lookup. Report whether write tools are available. If expected write tools are missing, ask me to check Allow actions that change site data and the selected actions in Hub, then refresh the connection. Do not claim success from saved configuration alone. Do not test writes during setup. Clarify the target site when ambiguous and ask for review before changing site data.'=>'قم بتوصيل تطبيق الذكاء الاصطناعي الخاص بي بـ PublishPress. أنشئ نصًا برمجيًا وقدم لي الأمر الدقيق في الطرفية لتشغيله.

1. اطلب مني اختيار تطبيق الذكاء الاصطناعي ونظام التشغيل الخاص بي (Windows أو macOS أو Linux). استخدم خيارات تفاعلية إذا كانت متاحة، وإلا استخدم خيارات مرقمة.
2. أنشئ النص باستخدام أدوات الملفات الخاصة بك. اطلب الإذن المحدد إذا لزم الأمر. إذا لم تتمكن من الكتابة محليًا، قم بإرفاق نص قابل للتنزيل. استخدم PowerShell على Windows ونص مناسب على macOS أو Linux. لا تتوقف عن شرح قيود الوصول أو تقديم JSON فقط.
3. قم بتكوين خادم stdio المحلي هذا:
الاسم: %3$s
اسم العرض: %4$s
الأمر: npx
المعطيات: -y @automattic/mcp-wordpress-remote@latest
البيئة: OAUTH_ENABLED=false، WP_API_URL=%1$s، WP_API_USERNAME=%2$s
اقرأ WP_API_PASSWORD من خلال مطالبة طرفية مخفية.
الوصول الكتابي إلى المركز: %5$s. يتم كشف الإجراءات المختارة بشكل فردي فقط.
4. تحقق من Node.js وnpx. إذا كانت مفقودة، أضف رابطًا إلى المثبت الرسمي واطلب مني إعادة فتح الطرفية. قم بعمل نسخة احتياطية من الإعدادات الحالية. استخدم محلل JSON/TOML أو أمر عميل مدعوم لدمج هذا الخادم فقط، مع الحفاظ على الإعدادات والمواقع الأخرى. توقف عند التكوين غير الصالح أو نقطة النهاية المتعارضة. إذا كنت تستبدل إضافة PublishPress القديمة لهذا الموقع، وجهني لتعطيل تلك الإضافة فقط لتجنب الاتصالات المكررة. اقتبس المسارات والقيم بأمان.
5. قدم تعليمات موجزة للتشغيل وإعادة التشغيل والموافقة. تحقق من خلال الاتصال أو قدم لي مطالبة للاختبار في التطبيق: أكد عنوان URL للموقع، أدرج الأدوات الفعلية وأجرِ بحثًا للقراءة فقط. أبلغ عما إذا كانت أدوات الكتابة متاحة. إذا كانت أدوات الكتابة المتوقعة مفقودة، اطلب مني التحقق من السماح بإجراءات تغيير بيانات الموقع والإجراءات المختارة في المركز، ثم قم بتحديث الاتصال. لا تدعي النجاح من التكوين المحفوظ فقط. لا تختبر الكتابات أثناء الإعداد. وضح الموقع المستهدف عند الغموض واطلب المراجعة قبل تغيير بيانات الموقع.','enabled'=>'مفعل','disabled'=>'معطل','Set up manually'=>'إعداد يدوي','Copy the configuration into your MCP client.'=>'انسخ التكوين إلى عميل MCP الخاص بك.','Actions available through PublishPress Hub.'=>'الإجراءات المتاحة من خلال مركز PublishPress.','List WordPress users'=>'قائمة مستخدمي WordPress','Find users by name or role. The optional primitive capability filter checks effective access within each candidate page. Visit all total_pages even when a filtered page is empty. No email addresses or secrets are returned.'=>'ابحث عن المستخدمين بالاسم أو الدور. يتحقق فلتر القدرة الأولية الاختياري من الوصول الفعال داخل كل صفحة مرشحة. قم بزيارة جميع total_pages حتى عندما تكون صفحة مرشحة فارغة. لا يتم إرجاع عناوين البريد الإلكتروني أو الأسرار.','Get WordPress user capabilities'=>'احصل على قدرات مستخدم WordPress','Resolve exactly one user_id or username and return their identity, roles and effective primitive capabilities. Never guess a user ID. Object-specific permissions require a separate check for that object.'=>'حدد بدقة user_id أو username واحد وأعد هويتهم وأدوارهم وقدراتهم الأولية الفعالة. لا تخمن أبدًا معرف المستخدم. تتطلب الأذونات الخاصة بالكائن تحققًا منفصلًا لذلك الكائن.','Find WordPress content'=>'ابحث عن محتوى WordPress','Search readable posts, pages or a REST-enabled custom post type. Returns actual IDs, titles and permalinks. Use post_type=page for pages. Resolve ambiguous titles before using a URL. Default status is publish. Private and draft requests enforce WordPress permissions.'=>'ابحث عن المشاركات والصفحات القابلة للقراءة أو نوع المشاركة المخصص المدعوم بواسطة REST. يُرجع معرفات فعلية وعناوين وروابط ثابتة. استخدم post_type=page للصفحات. قم بحل العناوين الغامضة قبل استخدام عنوان URL. الحالة الافتراضية هي النشر. تفرض طلبات خاصة والمسودات أذونات WordPress.','List WordPress post types'=>'قائمة أنواع مشاركات WordPress','List readable REST-enabled post types and the capability names used for each type. Use these names for content lookups and permission questions.'=>'قائمة أنواع المشاركات المدعومة بواسطة REST القابلة للقراءة وأسماء القدرات المستخدمة لكل نوع. استخدم هذه الأسماء للبحث عن المحتوى والأسئلة المتعلقة بالأذونات.','WordPress'=>'WordPress','Create WordPress user'=>'إنشاء مستخدم WordPress','Create a new user account with a known username, email and one editable role. Ask for missing details. WordPress validates role assignment permissions. MCP rejects administrator and any role granting administrator-level capabilities. A password is generated privately. By default WordPress emails the user a password setup link. Never guess an email or request a password in chat.'=>'إنشاء حساب مستخدم جديد باسم مستخدم معروف، وبريد إلكتروني ودور قابل للتعديل. اطلب التفاصيل الناقصة. WordPress يتحقق من أذونات تعيين الأدوار. يرفض MCP المدير وأي دور يمنح قدرات على مستوى المدير. يتم إنشاء كلمة مرور بشكل خاص. افتراضيًا، يرسل WordPress للمستخدم رابط إعداد كلمة المرور عبر البريد الإلكتروني. لا تخمن البريد الإلكتروني أو تطلب كلمة مرور في الدردشة.','Create WordPress content'=>'إنشاء محتوى WordPress','Create a post, page or REST-enabled custom post type. Use post_type=page for pages. Defaults to draft. Publish or schedule only when requested. WordPress checks creation, publishing and author-assignment permissions. Returns the actual ID and permalink.'=>'إنشاء منشور أو صفحة أو نوع منشور مخصص يدعم REST. استخدم post_type=page للصفحات. الافتراضي هو المسودة. انشر أو جدول فقط عند الطلب. يتحقق WordPress من أذونات الإنشاء والنشر وتعيين المؤلف. يُرجع المعرف الفعلي والرابط الثابت.','Update WordPress content'=>'تحديث محتوى WordPress','Edit an existing post, page or REST-enabled custom post by its verified ID. Find content first if the ID is unknown. Only supplied fields change. WordPress checks object, publishing and author-assignment permissions. No deletion, arbitrary metadata or options are supported.'=>'تحرير منشور أو صفحة أو منشور مخصص موجود من خلال معرّفه الموثق. ابحث عن المحتوى أولاً إذا كان المعرف غير معروف. تتغير الحقول المقدمة فقط. يتحقق WordPress من أذونات الكائن والنشر وتعيين المؤلف. لا يتم دعم الحذف أو البيانات الوصفية أو الخيارات التعسفية.','Use the exact input types shown in discovery.'=>'استخدم أنواع الإدخال الدقيقة المعروضة في الاكتشاف.','You cannot list users.'=>'لا يمكنك سرد المستخدمين.','Provide either a user ID or an exact username.'=>'قدم إما معرف مستخدم أو اسم مستخدم دقيق.','No matching user belongs to this site.'=>'لا يوجد مستخدم مطابق ينتمي إلى هذا الموقع.','You cannot inspect this user.'=>'لا يمكنك فحص هذا المستخدم.','Choose a REST-enabled post type.'=>'اختر نوع منشور يدعم REST.','This post type does not support content lookup.'=>'لا يدعم هذا النوع من المنشورات البحث عن المحتوى.','MCP tools cannot create users with administrator-level access. Use the WordPress Users screen for this change.'=>'لا يمكن لأدوات MCP إنشاء مستخدمين بإمكانية وصول على مستوى المدير. استخدم شاشة مستخدمي WordPress لهذا التغيير.','Provide at least one content field to update.'=>'قدم على الأقل حقل محتوى واحد للتحديث.','Choose an existing REST-enabled post type.'=>'اختر نوع منشور موجود يدعم REST.','This post type does not support content writes.'=>'لا يدعم هذا النوع من المنشورات الكتابة إلى المحتوى.','You cannot perform this operation.'=>'لا يمكنك إجراء هذه العملية.','Object must be loaded before initializing.'=>'يجب تحميل الكائن قبل التهيئة.','This license key is managed in wp-config.php and cannot be edited from the Hub.'=>'يتم إدارة مفتاح الترخيص هذا في wp-config.php ولا يمكن تحريره من المركز.','No license key found'=>'لم يتم العثور على مفتاح ترخيص','This license key is managed in wp-config.php and cannot be deactivated from the Hub.'=>'يتم إدارة مفتاح الترخيص هذا في wp-config.php ولا يمكن إلغاء تفعيله من المركز.','Invalid conflict resolution request.'=>'طلب حل النزاع غير صالح.','The selected plugin is not available for activation.'=>'الإضافة المحددة غير متاحة للتفعيل.','Cleanup was stopped because the selected plugin is not active or the other version is still loaded. Neither copy was deleted.'=>'تم إيقاف التنظيف لأن الإضافة المحددة غير نشطة أو أن النسخة الأخرى لا تزال محملة. لم يتم حذف أي نسخة.','The selected plugin is active, but the other version could not be removed. Please remove it from the Plugins screen.'=>'الإضافة المحددة نشطة، لكن لم يكن من الممكن إزالة النسخة الأخرى. يرجى إزالتها من شاشة الإضافات.','The selected plugin is no longer active. Please reactivate it from the Plugins screen.'=>'الإضافة المحددة لم تعد نشطة. يرجى إعادة تنشيطها من شاشة الإضافات.','No existing license key was found for this plugin.'=>'لم يتم العثور على مفتاح ترخيص موجود لهذه الإضافة.','Database Tables'=>'جداول قاعدة البيانات','PublishPress Plugins'=>'إضافات PublishPress','PublishPress Hub Debug Log'=>'سجل تصحيح مركز PublishPress','Debug Log'=>'سجل التصحيح','The debug log is empty.'=>'سجل التصحيح فارغ.','Version'=>'الإصدار','Debug Mode'=>'وضع التصحيح','Enabled'=>'مفعل','Disabled'=>'معطل','Generated At'=>'تم إنشاؤه في','Plugins'=>'الإضافات','No PublishPress plugins found.'=>'لم يتم العثور على أي إضافات PublishPress.','Tables'=>'الجداول','No database table information was available.'=>'لم تكن هناك معلومات عن جدول قاعدة البيانات متاحة.','Size'=>'الحجم','Engine'=>'المحرك','Rows'=>'الصفوف','Collation'=>'ترتيب','Charset'=>'مجموعة الأحرف','Total Database Size'=>'إجمالي حجم قاعدة البيانات','Not installed'=>'لم يتم التثبيت','Active'=>'نشط','Inactive'=>'غير نشط','unknown'=>'غير معروف','License'=>'الرخصة','Free plugin not set for plugin family: %s'=>'لم يتم تعيين إضافة مجانية لعائلة الإضافات: %s','Pro plugin not set for plugin family: %s'=>'لم يتم تعيين إضافة مدفوعة لعائلة الإضافات: %s','License activation error. Please try again later or contact support for help.'=>'حدث خطأ في تفعيل الرخصة. يرجى المحاولة مرة أخرى لاحقًا أو الاتصال بالدعم للحصول على المساعدة.','License deactivation error. Please try again later or contact support for help.'=>'حدث خطأ في إلغاء تفعيل الرخصة. يرجى المحاولة مرة أخرى لاحقًا أو الاتصال بالدعم للحصول على المساعدة.','This license is currently disabled. Please contact support for help.'=>'هذه الرخصة معطلة حاليًا. يرجى الاتصال بالدعم للحصول على المساعدة.','This license has expired. Please contact support to renew it.'=>'انتهت صلاحية هذه الرخصة. يرجى الاتصال بالدعم لتجديدها.','This license key could not be activated. It may be invalid, blocked, or not authorized for this plugin. Please verify the key and contact PublishPress support if the problem continues.'=>'لم يتم تفعيل مفتاح الرخصة. قد يكون غير صالح أو محظورًا أو غير مصرح به لهذه الإضافة. يرجى التحقق من المفتاح والاتصال بدعم PublishPress إذا استمر المشكلة.','This license cannot be used for this plugin. Please contact support for help.'=>'لا يمكن استخدام هذه الرخصة لهذه الإضافة. يرجى الاتصال بالدعم للحصول على المساعدة.','This license does not match the plugin you are trying to activate. Please contact support for assistance.'=>'هذه الرخصة لا تطابق الإضافة التي تحاول تفعيلها. يرجى الاتصال بالدعم للحصول على المساعدة.','License key does not match our records. Please contact support for assistance.'=>'مفتاح الرخصة لا يتطابق مع سجلاتنا. يرجى الاتصال بالدعم للحصول على المساعدة.','No license key provided. Please enter a valid license key.'=>'لم يتم تقديم مفتاح رخصة. يرجى إدخال مفتاح رخصة صالح.','Your site URL is required to activate the license. Please enter a valid site URL to continue.'=>'رابط موقعك مطلوب لتفعيل الرخصة. يرجى إدخال رابط موقع صالح للاستمرار.','License activation limit reached. Please contact support to upgrade or deactivate on another site.'=>'تم الوصول إلى حد تفعيل الرخصة. يرجى الاتصال بالدعم للترقية أو إلغاء التفعيل على موقع آخر.','This license cannot be activated. Please contact support for help.'=>'لا يمكن تفعيل هذه الرخصة. يرجى الاتصال بالدعم للحصول على المساعدة.','License server error. Please try again later or contact support for help.'=>'خطأ في خادم الرخصة. يرجى المحاولة مرة أخرى لاحقًا أو الاتصال بالدعم للحصول على المساعدة.','The license server returned an invalid response. Please try again later or contact support for help.'=>'أعاد خادم الرخصة استجابة غير صالحة. يرجى المحاولة مرة أخرى لاحقًا أو الاتصال بالدعم للحصول على المساعدة.','This license is inactive for this site. Please contact support for help.'=>'هذه الرخصة غير نشطة لهذا الموقع. يرجى الاتصال بالدعم للحصول على المساعدة.','Plugin activation failed. Please try again later or contact support for help.'=>'فشل تفعيل الإضافة. يرجى المحاولة مرة أخرى لاحقًا أو الاتصال بالدعم للحصول على المساعدة.','This action is not possible because the plugin is already installed.'=>'هذه العملية غير ممكنة لأن الإضافة مثبتة بالفعل.','Plugin deactivation failed. Please try again later or contact support for help.'=>'فشل إلغاء تفعيل الإضافة. يرجى المحاولة مرة أخرى لاحقًا أو الاتصال بالدعم للحصول على المساعدة.','Plugin family not found. Please contact support for help.'=>'لم يتم العثور على عائلة الإضافات. يرجى الاتصال بالدعم للحصول على المساعدة.','This action is not possible because both free and pro versions are installed. Please uninstall one version to continue.'=>'هذه العملية غير ممكنة لأن كل من الإصدارات المجانية والمدفوعة مثبتة. يرجى إلغاء تثبيت إصدار واحد للاستمرار.','Plugin installation failed. Please contact support for help.'=>'فشل تثبيت الإضافة. يرجى الاتصال بالدعم للحصول على المساعدة.','This action is not possible because the plugin is not activated. Please activate the plugin and try again.'=>'هذه العملية غير ممكنة لأن الإضافة غير مفعلة. يرجى تفعيل الإضافة والمحاولة مرة أخرى.','Plugin not found in our available plugins list. Please contact support for help.'=>'لم يتم العثور على الإضافة في قائمة الإضافات المتاحة لدينا. يرجى الاتصال بالدعم للحصول على المساعدة.','This action is not possible because the plugin is not installed. Please install the plugin and try again.'=>'هذه العملية غير ممكنة لأن الإضافة غير مثبتة. يرجى تثبيت الإضافة والمحاولة مرة أخرى.','Unknown license server error. Please try again later or contact support for help.'=>'خطأ غير معروف في خادم الرخصة. يرجى المحاولة مرة أخرى لاحقًا أو الاتصال بالدعم للحصول على المساعدة.','Sell digital products, programs, and services from your website.'=>'بيع المنتجات الرقمية والبرامج والخدمات من موقعك الإلكتروني.','Create and manage tags, categories, and taxonomy terms.'=>'إنشاء وإدارة العلامات والفئات والمصطلحات.','Organize taxonomy terms into groups and display them in clouds, tabs, and lists.'=>'تنظيم المصطلحات في مجموعات وعرضها في السحب، والألسنة، والقوائم.','Define tasks that authors must complete before publishing.'=>'تحديد المهام التي يجب على المؤلفين إكمالها قبل النشر.','Control who can edit and view your content.'=>'التحكم في من يمكنه تعديل وعرض المحتوى الخاص بك.','Create, manage and display authors for your content.'=>'إنشاء وإدارة وعرض المؤلفين لمحتواك.','All the tools you need to improve the block editor.'=>'جميع الأدوات التي تحتاجها لتحسين محرر الكتل.','Control your admin area and user roles.'=>'التحكم في منطقة الإدارة الخاصة بك وأدوار المستخدمين.','Schedule changes to your posts.'=>'جدولة التغييرات على منشوراتك.','Organize, schedule, and plan your publishing.'=>'تنظيم، جدولة، والتخطيط للنشر الخاص بك.','Approve and schedule new versions to your published posts.'=>'الموافقة على جدولة إصدارات جديدة لمنشوراتك المنشورة.','Organize your posts into issues or series.'=>'تنظيم منشوراتك في قضايا أو سلاسل.','Create custom URLs for your posts and external links.'=>'إنشاء عناوين URL مخصصة لمنشوراتك والروابط الخارجية.','Create custom statuses and publishing workflows.'=>'إنشاء حالات مخصصة وسير عمل النشر.','Dependency "%s" not found in container.'=>'لم يتم العثور على الاعتماد "%s" في الحاوية.','Error validating license: %s'=>'خطأ في التحقق من الترخيص: %s','Error getting license info: %s'=>'خطأ في الحصول على معلومات الترخيص: %s','The license server denied this request. This can happen when a license key or site has been blocked. Please contact PublishPress support for help.'=>'رفض خادم الترخيص هذا الطلب. يمكن أن يحدث هذا عندما يتم حظر مفتاح الترخيص أو الموقع. يرجى الاتصال بدعم PublishPress للحصول على المساعدة.','Too many requests. Please try again later.'=>'عدد كبير جدًا من الطلبات. يرجى المحاولة مرة أخرى لاحقًا.','An error occurred while processing your request.'=>'حدث خطأ أثناء معالجة طلبك.','Template not found: %s'=>'لم يتم العثور على القالب: %s','Path cannot be empty'=>'لا يمكن أن تكون المسار فارغًا','File extension cannot be empty'=>'لا يمكن أن تكون امتداد الملف فارغًا','Invalid file path: null byte detected'=>'مسار الملف غير صالح: تم اكتشاف بايت فارغ','Invalid file path: directory traversal detected'=>'مسار الملف غير صالح: تم اكتشاف تجاوز الدليل','Invalid file path: parent directory does not exist: %s'=>'مسار الملف غير صالح: الدليل الأب غير موجود: %s','Invalid file path: unable to resolve path'=>'مسار الملف غير صالح: غير قادر على حل المسار','Invalid file path: operation not allowed outside permitted directories'=>'مسار الملف غير صالح: العملية غير مسموح بها خارج الأدلة المسموح بها','Download URL failed WordPress validation'=>'فشل عنوان URL للتنزيل في التحقق من WordPress','Downloaded plugin file does not exist'=>'ملف المكون الإضافي الذي تم تنزيله غير موجود','Downloaded plugin file is empty'=>'ملف المكون الإضافي الذي تم تنزيله فارغ','Cannot read downloaded plugin file'=>'لا يمكن قراءة ملف المكون الإضافي الذي تم تنزيله','Downloaded file is not a valid ZIP archive. The download URL may be returning an error page.'=>'الملف الذي تم تنزيله ليس أرشيف ZIP صالح. قد يُعيد عنوان URL للتنزيل صفحة خطأ.','Failed to unzip plugin file: %s'=>'فشل في فك ضغط ملف المكون الإضافي: %s','Failed to unzip plugin file'=>'فشل في فك ضغط ملف المكون الإضافي','Failed to activate plugin: %s'=>'فشل في تفعيل المكون الإضافي: %s','Resolve conflicts for network-active plugins from Network Admin.'=>'حل النزاعات للمكونات الإضافية النشطة في الشبكة من إدارة الشبكة.','Activation recovery failed. Both plugin copies were retained. Please restore the previous version from the Plugins screen.'=>'فشل استعادة التفعيل. تم الاحتفاظ بنسختين من المكون الإضافي. يرجى استعادة النسخة السابقة من شاشة المكونات الإضافية.','The other plugin could not be deactivated.'=>'لم يتمكن من إلغاء تنشيط المكون الإضافي الآخر.','The selected plugin did not remain active.'=>'لم يبق المكون الإضافي المحدد نشطًا.','The selected plugin could not be activated. Neither copy was deleted and the previous activation settings were restored.'=>'لم يتم تفعيل الإضافة المحددة. لم يتم حذف أي نسخة وتم استعادة إعدادات التفعيل السابقة.','Failed to delete plugin: %s'=>'فشل في حذف الإضافة: %s','No update available for this plugin'=>'لا توجد تحديثات متاحة لهذه الإضافة','Invalid update information for this plugin'=>'معلومات التحديث غير صالحة لهذه الإضافة','Update package not available'=>'حزمة التحديث غير متاحة','Failed to update plugin: %s'=>'فشل في تحديث الإضافة: %s','Plugin update failed'=>'فشل تحديث الإضافة','Invalid download URL provided'=>'رابط التنزيل المقدم غير صالح','Download URL must use HTTP or HTTPS protocol'=>'يجب أن يستخدم رابط التنزيل بروتوكول HTTP أو HTTPS','Download URL is not from an allowed domain: %s'=>'رابط التنزيل ليس من نطاق مسموح به: %s','Could not create a temporary package file'=>'تعذر إنشاء ملف حزمة مؤقت','Failed to download plugin: %s'=>'فشل في تنزيل الإضافة: %s','The plugin package download failed'=>'فشل تنزيل حزمة الإضافة','Failed to get plugin information: %s'=>'فشل في الحصول على معلومات الإضافة: %s','MCP Adapter could not be installed or activated. Use the plugin page or contact your host.'=>'تعذر تثبيت أو تفعيل موصل MCP. استخدم صفحة الإضافة أو اتصل بمزود الخدمة الخاص بك.','MCP Adapter activated.'=>'تم تفعيل موصل MCP.','.'=>'.']];